cat >> /workspace/Dev.v <<'EOF'

(* ---------------- the parallel-reduction diamond ---------------- *)

Lemma Par_diamond : forall (P:econtext) psi (a b:tm), Par P psi a b ->
  forall c, Par P psi a c -> exists d, Par P psi b d /\ Par P psi c d.
Proof.
  intros PP ps0 a0 b0 H.
  apply (Par_mut
    (fun P psi a b (_:Par P psi a b) =>
       forall c, Par P psi a c -> exists d, Par P psi b d /\ Par P psi c d)
    (fun P psi phi0 a b (_:CPar P psi phi0 a b) =>
       forall c, CPar P psi phi0 a c -> exists d, CPar P psi phi0 b d /\ CPar P psi phi0 c d)).
  1: { (* Par_Refl *) eapply Par_dia_refl; eassumption. }
  1: { (* Par_Pi *) eapply Par_dia_pi; eassumption. }
  1: { (* Par_AppBeta *) eapply Par_dia_appbeta; eassumption. }
  1: { (* Par_App *) eapply Par_dia_app; eassumption. }
  1: { (* Par_Abs *) eapply Par_dia_abs; eassumption. }
  1: { (* Par_WSigma *) eapply Par_dia_wsigma; eassumption. }
  1: { (* Par_WPair *) eapply Par_dia_wpair; eassumption. }
  1: { (* Par_WPairBeta *) eapply Par_dia_wpairbeta; eassumption. }
  1: { (* Par_LetPair *) eapply Par_dia_letpair; eassumption. }
  1: { (* Par_SSigma *) eapply Par_dia_ssigma; eassumption. }
  1: { (* Par_SPair *) eapply Par_dia_spair; eassumption. }
  1: { (* Par_Proj1Beta *) eapply Par_dia_proj1beta; eassumption. }
  1: { (* Par_Proj1 *) eapply Par_dia_proj1; eassumption. }
  1: { (* Par_Proj2Beta *) eapply Par_dia_proj2beta; eassumption. }
  1: { (* Par_Proj2 *) eapply Par_dia_proj2; eassumption. }
  1: { (* Par_Sum *) eapply Par_dia_sum; eassumption. }
  1: { (* Par_Inj1 *) eapply Par_dia_inj1; eassumption. }
  1: { (* Par_Inj2 *) eapply Par_dia_inj2; eassumption. }
  1: { (* Par_CaseBeta1 *) eapply Par_dia_casebeta1; eassumption. }
  1: { (* Par_CaseBeta2 *) eapply Par_dia_casebeta2; eassumption. }
  1: { (* Par_Case *) eapply Par_dia_case; eassumption. }
  1: { (* CPar_Leq *) eapply Par_dia_cpar_leq; eassumption. }
  1: { (* CPar_Nleq *) eapply Par_dia_cpar_nleq; eassumption. }
  exact H.
Qed.
EOF
