    eapply CG_Nleq.
    + exact l.
    + exact n.
    + apply uniq_swap_mid; exact u.
  }
  19: {
    (* CG_Leq *) intros P psi phi0 a i g IHg C dx dgx dy dgy Q Heq. subst P.
    eapply CG_Leq.
    + exact i.
    + apply IHg; reflexivity.
  }
  18: {
    (* G_TmUnit *) intros P psi u C dx dgx dy dgy Q Heq. subst P.
    apply G_TmUnit. apply uniq_swap_mid; exact u.
  }
  17: {
    (* G_TyUnit *) intros P psi u C dx dgx dy dgy Q Heq. subst P.
    apply G_TyUnit. apply uniq_swap_mid; exact u.
  }
  16: {
    (* G_Case *) intros P psi psi0 a b1 b2 g IHg g0 IHg0 g1 IHg1 i C dx dgx dy dgy Q Heq. subst P.
    eapply G_Case.
    + apply IHg; reflexivity.
    + apply IHg0; reflexivity.
    + apply IHg1; reflexivity.
    + exact i.
  }
  15: {
